const out=[];for(const f of files){let s=fs.readFileSync(f,'utf8');const a=(s.match(/\bretryPolicy\b/g)||[]).length,b=(s.match(/maxAttempts: 3(?!\d)/g)||[]).length;s=s.replace(/\bretryPolicy\b/g,'backoffPolicy').replace(/maxAttempts: 3(?!\d)/g,'maxAttempts: 5');fs.writeFileSync(f,s);out.push(`${f} ${a}/${b}`);}
const left=(await $`grep -rnE "retryPolicy|maxAttempts: 3" src test`).stdout;
